[{"order":1,"type":"heading","text":"NativeScript with React (via Alternatives) and Plain TypeScript"},{"order":2,"type":"paragraph","text":"This tutorial explores building native mobile applications using NativeScript combined with TypeScript. While NativeScript natively supports Angular, Vue, Svelte, and Plain TypeScript, React is typically used via community alternatives or bindings. Here, we focus on setting up a robust architecture using Plain TypeScript to understand the underlying native rendering engine."},{"order":3,"type":"subheading","text":"Prerequisites and Environment Setup"},{"order":4,"type":"paragraph","text":"Before you begin, ensure you have Node.js installed along with the NativeScript CLI. You will also need Xcode for iOS development or Android Studio for Android development."},{"order":5,"type":"code","text":"npm install -g nativescript"},{"order":6,"type":"subheading","text":"Creating a Plain TypeScript Project"},{"order":7,"type":"paragraph","text":"Initialize a new NativeScript project using the TypeScript template. This gives you a clean slate without any specific UI framework overhead."},{"order":8,"type":"code","text":"ns create MyTsApp --ts"},{"order":9,"type":"subheading","text":"Understanding the Project Structure"},{"order":10,"type":"bullet_point","text":"app/app.ts: The entry point of your application where bootstrapping occurs."},{"order":11,"type":"bullet_point","text":"app/main-page.ts: Handles the logic and view-model for the main application screen."},{"order":12,"type":"bullet_point","text":"app/main-page.xml: Defines the native UI components using XML markup."},{"order":13,"type":"subheading","text":"Writing the View (XML)"},{"order":14,"type":"paragraph","text":"Open app/main-page.xml and define a simple layout containing a label and a button. NativeScript maps these XML tags directly to native UI elements (e.g., android.widget.Button and UIButton on iOS)."},{"order":15,"type":"code","text":"<Page xmlns="http://schemas.nativescript.org/tns.xsd" navigatingTo="onNavigatingTo">
  <StackLayout class="p-20">
    <Label text="Welcome to NativeScript!" class="h1 text-center" />
    <Button text="Tap me" tap="onButtonTap" class="btn btn-primary" />
  </StackLayout>
</Page>"},{"order":16,"type":"subheading","text":"Implementing the Logic (TypeScript)"},{"order":17,"type":"paragraph","text":"Open app/main-page.ts and implement the event handlers referenced in your XML file. TypeScript provides type safety for NativeScript modules."},{"order":18,"type":"code","text":"import { EventData, Button, Page } from '@nativescript/core';

export function onNavigatingTo(args: EventData) {
  const page = <Page>args.object;
}

export function onButtonTap(args: EventData) {
  const button = <Button>args.object;
  button.text = "Tapped!";
}"},{"order":19,"type":"subheading","text":"Addressing the React Paradigm"},{"order":20,"type":"paragraph","text":"If you prefer React's declarative component model and state management hooks, you can look into community-driven renderers like react-nativescript. These alternatives translate JSX elements directly into NativeScript modules, bridging the gap between React DOM concepts and native mobile UI components."},{"order":21,"type":"subheading","text":"Running Your Application"},{"order":22,"type":"paragraph","text":"To run your application on an emulator or a connected physical device, use the NativeScript CLI preview or run commands."},{"order":23,"type":"code","text":"ns run android
ns run ios"}]
